begin;
drop function if exists public.app_kombax_social_mutate_v049(text,jsonb,uuid);
drop function if exists public.app_kombax_social_estado_v049(uuid);
drop table if exists public.kombax_aceptaciones_globales;
create or replace function public.app_kombax_social_puede_publicar_v041(p_social_id uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.kombax_social_perfiles sp where sp.id=p_social_id and sp.visible and sp.estado='activo' and sp.publicar_habilitado and ((sp.sujeto_tipo='miembro' and exists(select 1 from public.identidades_sociales i where i.id=sp.identidad_social_id and i.perfil_id=auth.uid() and i.estado='activa') and public.app_kombax_capacidad_club_v041((select i.club_origen_id from public.identidades_sociales i where i.id=sp.identidad_social_id),'social.publish')) or (sp.sujeto_tipo='club' and public.app_kombax_capacidad_club_v041(sp.club_id,'social.publish') and exists(select 1 from public.miembros_club m where m.club_id=sp.club_id and m.perfil_id=auth.uid() and m.activo and (m.rol in ('direccion','secretaria','comunicacion') or coalesce(m.coordinacion,false)))) or (sp.sujeto_tipo='perfil_directo' and exists(select 1 from public.perfiles_kombax_directos d join public.kombax_entitlements e on e.sujeto_tipo='perfil_directo' and e.sujeto_id=d.id and e.capacidad_clave='social.publish' and e.activa and e.inicia_en<=now() and (e.termina_en is null or e.termina_en>now()) where d.id=sp.perfil_directo_id and d.perfil_id=auth.uid() and d.estado='activo' and d.verificacion_estado='verificado')))); $$;
revoke all on function public.app_kombax_social_puede_publicar_v041(uuid) from public,anon;grant execute on function public.app_kombax_social_puede_publicar_v041(uuid) to authenticated;
create or replace function public.app_kombax_social_contactable_v041(p_social_id uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.kombax_social_perfiles sp where sp.id=p_social_id and sp.visible and sp.estado='activo' and ((sp.sujeto_tipo in ('club','perfil_directo') and sp.contacto_habilitado) or exists(select 1 from public.identidades_sociales i join public.socios s on s.id=i.socio_origen_id and s.club_id=i.club_origen_id where i.id=sp.identidad_social_id and i.estado='activa' and s.estado='activo' and s.fecha_nacimiento is not null and extract(year from age(current_date,s.fecha_nacimiento))>=18))); $$;
revoke all on function public.app_kombax_social_contactable_v041(uuid) from public,anon;grant execute on function public.app_kombax_social_contactable_v041(uuid) to authenticated;
alter table public.perfiles_kombax_directos drop column if exists social_normas_version,drop column if exists social_activado_en,drop column if exists social_activo;
notify pgrst,'reload schema';
commit;
